# Load required libraries
library(readr)
library(dplyr)
library(tidyr)
library(purrr)

# Define paths and filenames
files <- list(
  wave_one = "data/input/wave_one_lsype_young_person_2020.tab",
  wave_two = "data/input/wave_two_lsype_young_person_2020.tab",
  wave_three = "data/input/wave_three_lsype_young_person_2020.tab",
  wave_four = "data/input/wave_four_lsype_young_person_2020.tab",
  wave_six = "data/input/wave_six_lsype_young_person_2020.tab",
  wave_seven = "data/input/wave_seven_lsype_young_person_2020.tab",
  ns8 = "data/input/ns8_2015_self_completion.tab",
  ns9 = "data/input/ns9_2022_main_interview.tab"
)

# Load all files
load_files <- function(file_path) {
  read_delim(file_path, delim = "\t")
}

data_list <- map(files, load_files)

# Merge all datasets by NSID
merged_data <- reduce(data_list, full_join, by = "NSID")

# Define age mapping for source variables
age_mapping <- tibble(
  wave = c("W1", "W2", "W3", "W4", "W6", "W7", "W8", "W9"),
  age = c(14, 15, 16, 17, 19, 20, 25, 32)
)

# Function to map missing values to standard codes
map_missing <- function(x) {
  if (is.numeric(x)) {
    replace(x, is.na(x), -3)
  } else {
    x
  }
}

# Function to convert 'ever had alcohol' variables to binary (1 = Yes, 2 = No)
convert_alcever <- function(x) {
  map_missing(x)
}

# Function to determine the earliest age of alcohol consumption
determine_alcfst <- function(row) {
  # Define the order of waves to check (youngest to oldest)
  waves_order <- c("W1", "W2", "W3", "W4", "W6", "W7", "W8", "W9")

  # Check each wave in order to find the earliest age with a 'Yes' response
  for (wave in waves_order) {
    alcever_var <- paste0(wave, "alceverYP")
    if (alcever_var %in% colnames(row)) {
      response <- row[[alcever_var]]
      if (response == 1) {
        age <- age_mapping$age[age_mapping$wave == wave]
        return(age)
      }
    }

    # Special handling for W8 and W9 which use AUDIT1
    audit_var <- paste0(wave, "AUDIT1")
    if (audit_var %in% colnames(row)) {
      response <- row[[audit_var]]
      if (response != 1) {  # Not 'Never'
        age <- age_mapping$age[age_mapping$wave == wave]
        return(age)
      }
    }
  }

  # If no 'Yes' found, return 99 (never drank alcohol)
  return(99)
}

# Create alcfst variable
merged_data <- merged_data %>%
  rowwise() %>%
  mutate(alcfst = determine_alcfst(c_across())) %>%
  ungroup()

# Select only NSID and alcfst for the output
output_data <- merged_data %>% select(NSID, alcfst)

# Write output to CSV
write_csv(output_data, "data/output/cleaned_data.csv")

