  for (wave in waves_order) {
    # Check for W1-W7 variables
    alcever_var <- paste0(wave, "alceverYP")
    if (alcever_var %in% colnames(row)) {
      response <- row[[alcever_var]]
      if (!is.na(response) && response == 1) {
        age <- age_mapping$age[age_mapping$wave == wave]
        return(age)
      }
